var maxDepth = function(s) {
    let depth = 0; // current nesting level
    let maxD  = 0; // maximum depth seen

    for (const c of s) {
        if (c === '(') {
            depth++;
            maxD = Math.max(maxD, depth); // update max after opening
        } else if (c === ')') {
            depth--;
        }
        // Ignore non-parenthesis characters
    }
    return maxD;
};
